from pathlib import Path
B=Path('astrafinalplan/implementation/batch04')
(B/'stage/64/test/checkout.test.ts').write_text('''import {test,before,after} from "node:test";
import assert from "node:assert/strict";
import {database,request} from "./database.js";
let h:Awaited<ReturnType<typeof database>>;
before(async()=>{h=await database();for(const id of [1,2]){await h.db("users").insert({id,email:`u${id}@example.com`,password_hash:"demo",display_name:"Learner"});await h.db("addresses").insert({id,user_id:id,full_name:"Learner",street_line_1:"1 Test St",city:"Test",state:"CA",zip_code:"00000"});}});after(async()=>{if(h)await h.close();});
const api=(path:string,method="GET",body?:unknown,user=1)=>request(h.origin,"/api"+path,method,body,{"x-demo-user-id":String(user)});
async function product(sku:string,stock:number){return(await h.db("products").insert({name:sku,slug:sku,sku,price:10,stock_quantity:stock}).returning("*"))[0];}
async function checkout(user:number){return api("/checkout","POST",{addressId:user,shippingMethod:"standard",paymentMethod:"mock_card"},user);}
test("cumulative additions and edits cannot exceed stock",async()=>{const p=await product("bounds",3);assert.equal((await api("/cart/items","POST",{productId:p.id,quantity:2})).status,200);assert.equal((await api("/cart/items","POST",{productId:p.id,quantity:2})).status,400);assert.equal((await api(`/cart/items/${p.id}`,"PUT",{quantity:4})).status,400);assert.equal((await h.db("cart_items").where({product_id:p.id}).first()).quantity,2);await api(`/cart/items/${p.id}`,"DELETE");});
test("two buyers cannot buy the same last unit",async()=>{const p=await product("last",1);for(const user of [1,2])await api("/cart/items","POST",{productId:p.id,quantity:1},user);const result=await Promise.all([checkout(1),checkout(2)]);assert.deepEqual(result.map(r=>r.status).sort(),[201,400],JSON.stringify(result));assert.equal((await h.db("products").where({id:p.id}).first()).stock_quantity,0);assert.equal(Number((await h.db("order_items").where({product_id:p.id}).count("* as n").first()).n),1);await h.db("cart_items").delete();});
test("double checkout makes one order and late failure preserves cart and stock",async()=>{const p=await product("rollback",5);await api("/cart/items","POST",{productId:p.id,quantity:1});await h.db.raw(`CREATE FUNCTION reject_order_item() RETURNS trigger LANGUAGE plpgsql AS $$ BEGIN RAISE EXCEPTION 'test failure'; END $$; CREATE TRIGGER reject_order_item BEFORE INSERT ON order_items FOR EACH ROW EXECUTE FUNCTION reject_order_item();`);assert.equal((await checkout(1)).status,500);assert.equal((await h.db("products").where({id:p.id}).first()).stock_quantity,5);assert.ok(await h.db("cart_items").where({product_id:p.id}).first());await h.db.raw("DROP TRIGGER reject_order_item ON order_items");const result=await Promise.all([checkout(1),checkout(1)]);assert.deepEqual(result.map(r=>r.status).sort(),[201,400]);assert.equal((await h.db("products").where({id:p.id}).first()).stock_quantity,4);});
''')
(B/'stage/65/test/booking.test.ts').write_text('''import {test,before,after} from "node:test";
import assert from "node:assert/strict";
import {database,request} from "./database.js";
let h:Awaited<ReturnType<typeof database>>;
before(async()=>{h=await database();await h.db("users").insert([{id:1,name:"Provider",email:"p@example.com",role:"provider"},{id:4,name:"Customer",email:"c@example.com",role:"customer"}]);await h.db("provider_profiles").insert({id:1,user_id:1});await h.db("services").insert({id:1,provider_id:1,name:"Consultation",duration_minutes:30,price:10});});after(async()=>{if(h)await h.close();});
const api=(path:string,method="POST",body?:unknown)=>request(h.origin,"/api"+path,method,body,{"x-user-id":"4"});
const book=(startTime:string)=>api("/appointments","POST",{providerId:1,serviceId:1,startTime});
test("concurrent bookings for one slot yield one appointment and one conflict",async()=>{const results=await Promise.all([book("2099-01-01T10:00:00Z"),book("2099-01-01T10:00:00Z")]);assert.deepEqual(results.map(r=>r.status).sort(),[201,409],JSON.stringify(results));assert.equal(Number((await h.db("appointments").count("* as n").first()).n),1);assert.equal(Number((await h.db("notifications").count("* as n").first()).n),1);});
test("adjacent appointment works; conflicting reschedule leaves its old time intact",async()=>{const a=await book("2099-01-01T10:30:00Z");assert.equal(a.status,201);const id=a.data.data.id;const r=await api(`/appointments/${id}/reschedule`,"PUT",{startTime:"2099-01-01T10:15:00Z"});assert.equal(r.status,409);assert.equal(new Date((await h.db("appointments").where({id}).first()).start_time).toISOString(),"2099-01-01T10:30:00.000Z");});
test("notification insert failure rolls the booking back",async()=>{await h.db.raw(`CREATE FUNCTION reject_notification() RETURNS trigger LANGUAGE plpgsql AS $$ BEGIN RAISE EXCEPTION 'test failure'; END $$; CREATE TRIGGER reject_notification BEFORE INSERT ON notifications FOR EACH ROW EXECUTE FUNCTION reject_notification();`);const count=(await h.db("appointments").count("* as n").first()).n;assert.equal((await book("2099-01-02T10:00:00Z")).status,500);assert.equal((await h.db("appointments").count("* as n").first()).n,count);});
''')
(B/'stage/66/test/environments.test.ts').write_text('''import {test,before,after} from "node:test";
import assert from "node:assert/strict";
import {database,request} from "./database.js";
let h:Awaited<ReturnType<typeof database>>,a:number,b:number,other:number;
before(async()=>{h=await database();await h.db("users").insert([1,2].map(id=>({id,name:"Learner",email:`u${id}@example.com`})));a=(await h.db("environments").insert({user_id:1,name:"Local",is_active:true}).returning("id"))[0].id;b=(await h.db("environments").insert({user_id:1,name:"Staging"}).returning("id"))[0].id;other=(await h.db("environments").insert({user_id:2,name:"Other",is_active:true}).returning("id"))[0].id;});after(async()=>{if(h)await h.close();});
const api=(path:string,method="GET",body?:unknown)=>request(h.origin,"/api"+path,method,body,{"x-user-id":"1"});
test("failed activation preserves the previous active environment",async()=>{for(const id of [other,999999])assert.equal((await api(`/environments/${id}/activate`,"POST",{})).status,404);assert.equal((await h.db("environments").where({id:a}).first()).is_active,true);});
test("concurrent activation and metadata edits retain one active environment per user",async()=>{const results=await Promise.all([api(`/environments/${a}/activate`,"POST",{}),api(`/environments/${b}/activate`,"POST",{})]);assert.deepEqual(results.map(r=>r.status),[200,200]);assert.equal((await h.db("environments").where({user_id:1,is_active:true})).length,1);assert.equal((await api(`/environments/${a}`,"PUT",{is_active:true})).status,200);assert.equal((await h.db("environments").where({user_id:1,is_active:true})).length,1);assert.equal((await h.db("environments").where({id:other}).first()).is_active,true);});
test("variable replacement accepts arrays, rejects duplicate keys atomically, and supports clearing",async()=>{const path=`/environments/${a}/variables`;assert.equal((await api(path,"PUT",[{key:"BASE_URL",value:"http://localhost:3000"}])).status,200);assert.equal((await api(path,"PUT",[{key:"KEY",value:"one"},{key:" KEY ",value:"two"}])).status,400);const saved=await h.db("env_variables").where({environment_id:a});assert.equal(saved.length,1);assert.equal(saved[0].key,"BASE_URL");assert.equal((await api(`/environments/${other}/variables`,"PUT",[])).status,404);assert.equal((await api(path,"PUT",[])).status,200);assert.equal((await h.db("env_variables").where({environment_id:a})).length,0);});
''')
